import Link from "next/link";
import { q } from "@/lib/db";
import { pageMember } from "@/lib/page";
import { fmtDateTime } from "@/lib/time";
import { Card } from "@/components/ui";

export const metadata = { title: "Conversations" };

const OUTCOME: Record<string, string> = { booked: "Booked", cancelled: "Cancelled a booking", rescheduled: "Moved a booking", escalated: "Handed to staff", answered: "Answered", abandoned: "Left" };

export default async function ConversationsPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const { business } = await pageMember(slug, "conversations.read");
  const rows = await q<{ id: string; status: string; outcome: string | null; turn: number; updated_at: Date; escalation: { reason?: string; summary?: string; customer_name?: string; customer_contact?: string } | null; first: string | null; reference: string | null; channel: string }>(
    `SELECT c.id, c.status, c.outcome, c.turn, c.updated_at, c.escalation, c.channel, r.reference,
            (SELECT content FROM messages m WHERE m.conversation_id = c.id AND m.role = 'user' ORDER BY m.id LIMIT 1) AS first
       FROM conversations c LEFT JOIN reservations r ON r.id = c.reservation_id
      WHERE c.business_id = $1 AND c.turn > 0
      ORDER BY (c.status = 'escalated') DESC, c.updated_at DESC LIMIT 100`, [business.id]);
  const waiting = rows.filter((r) => r.status === "escalated");
  const others = rows.filter((r) => r.status !== "escalated");

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-3xl font-extrabold">Conversations</h1>
        <p className="text-ink-soft">What customers asked the assistant, and the ones it handed to you.</p>
      </div>
      <section>
        <h2 className="mb-2 text-lg font-bold">Waiting for staff <span className="font-sans text-base font-medium text-muted">{waiting.length}</span></h2>
        {waiting.length === 0 ? <Card className="px-4 py-4 text-ink-soft">Nothing is waiting. When the assistant cannot help a customer, the conversation appears here with a summary.</Card> : (
          <ul className="space-y-3">
            {waiting.map((c) => (
              <li key={c.id}>
                <Link href={`/app/${slug}/conversations/${c.id}`} className="block rounded-2xl bg-white p-4 ring-2 ring-rose/40 hover:bg-paper">
                  <p className="font-semibold">{c.escalation?.reason ?? "Needs a person"}</p>
                  <p className="mt-0.5 line-clamp-2 text-[15px] text-ink-soft">{c.escalation?.summary}</p>
                  <p className="mt-1.5 text-[15px]">
                    {c.escalation?.customer_contact ? <>Reach {c.escalation.customer_name ?? "the customer"} at <strong>{c.escalation.customer_contact}</strong></> : <span className="text-amber">The customer left no contact detail.</span>}
                  </p>
                  <p className="mt-1 text-[13px] text-muted">{fmtDateTime(c.updated_at, business.timezone)}</p>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </section>
      <section>
        <h2 className="mb-2 text-lg font-bold">Recent</h2>
        <Card>
          {others.length === 0 ? <p className="px-4 py-4 text-ink-soft">No conversations yet.</p> : (
            <ul className="divide-y divide-line">
              {others.map((c) => (
                <li key={c.id}>
                  <Link href={`/app/${slug}/conversations/${c.id}`} className="flex items-center gap-4 px-4 py-3 hover:bg-paper">
                    <div className="min-w-0 flex-1">
                      <p className="truncate font-medium">{c.first ?? "(no message)"}</p>
                      <p className="text-[13px] text-muted">{fmtDateTime(c.updated_at, business.timezone)}, {c.turn} {c.turn === 1 ? "message" : "messages"}{c.channel === "whatsapp" ? ", WhatsApp" : c.channel === "sms" ? ", text message" : c.channel === "voice" ? ", phone call" : ""}</p>
                    </div>
                    <span className="shrink-0 text-[15px] font-semibold text-ink-soft">{c.outcome ? OUTCOME[c.outcome] : "No booking"}{c.reference ? ` ${c.reference}` : ""}</span>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </section>
    </div>
  );
}
